# Phase 2: external item definitions, extracted SVG icons and category catalogs.
# Baseline a9a69a9. Defaults to preview; use -Apply with Godot closed.
# No downloads, commits, save changes or separate backup files.
[CmdletBinding()]
param([string]$ProjectRoot = $PSScriptRoot, [switch]$Apply)
$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest
$utf8 = New-Object System.Text.UTF8Encoding($false)

# =========================================================
# Compare content consistently across Git CRLF/LF and UTF-8 BOM differences.
function Get-TextHash([string]$Text) {
    $normalized = $Text.TrimStart([char]0xFEFF).Replace("`r`n", "`n").Replace("`r", "`n").TrimEnd([char]10) + "`n"
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try { return ([BitConverter]::ToString($sha.ComputeHash($utf8.GetBytes($normalized)))).Replace('-', '').ToLowerInvariant() }
    finally { $sha.Dispose() }
}

# =========================================================
# Decode the complete reviewed file payload without network access.
$encoded = @'

'@
$inputStream = New-Object System.IO.MemoryStream(,[Convert]::FromBase64String($encoded))
$gzip = New-Object System.IO.Compression.GZipStream($inputStream, [IO.Compression.CompressionMode]::Decompress)
$reader = New-Object System.IO.StreamReader($gzip, $utf8)
try { $payload = $reader.ReadToEnd() | ConvertFrom-Json }
finally { $reader.Dispose(); $gzip.Dispose(); $inputStream.Dispose() }

$ProjectRoot = [IO.Path]::GetFullPath($ProjectRoot)
if (!(Test-Path -LiteralPath (Join-Path $ProjectRoot 'project.godot') -PathType Leaf)) {
    throw 'ProjectRoot must contain project.godot. Put this script in the project root or supply -ProjectRoot.'
}
$states = @{}
$complete = $true
foreach ($file in $payload.files) {
    if ((Get-TextHash $file.content) -ne $file.after) { throw "Corrupt embedded payload: $($file.path)" }
    $path = Join-Path $ProjectRoot $file.path
    if (Test-Path -LiteralPath $path -PathType Leaf) {
        $states[$file.path] = Get-TextHash ([IO.File]::ReadAllText($path))
    } elseif (Test-Path -LiteralPath $path) { throw "Expected a file: $path" }
    else { $states[$file.path] = $null }
    if ($states[$file.path] -ne $file.after) { $complete = $false }
}

# =========================================================
# Reject changed dependencies and partial/conflicting installs before any write.
foreach ($guard in $payload.guards.PSObject.Properties) {
    $path = Join-Path $ProjectRoot $guard.Name
    if (!(Test-Path -LiteralPath $path -PathType Leaf)) { throw "Missing baseline dependency: $($guard.Name)" }
    $expected = $guard.Value
    if ($complete -and $states.ContainsKey($guard.Name)) { $expected = $states[$guard.Name] }
    if ((Get-TextHash ([IO.File]::ReadAllText($path))) -ne $expected) {
        throw "Source differs from reviewed baseline (or partial install): $($guard.Name). No files written."
    }
}
if ($complete) { Write-Host 'Phase 2 is already installed. No files changed.'; return }
foreach ($file in $payload.files) {
    $current = $states[$file.path]
    if ($null -eq $file.before) {
        if ($null -ne $current) { throw "New destination already exists (or partial install): $($file.path). No files written." }
    } elseif ($current -ne $file.before) {
        throw "Unexpected source or partial install: $($file.path). No files written."
    }
    if ($file.path.EndsWith('.tres')) {
        foreach ($match in [regex]::Matches($file.content, 'path="res://([^"]+)"')) {
            $ref = $match.Groups[1].Value
            $included = @($payload.files | Where-Object { $_.path -eq $ref }).Count -gt 0
            if (!$included -and !(Test-Path -LiteralPath (Join-Path $ProjectRoot $ref) -PathType Leaf)) {
                throw "Missing resource dependency: $ref. No files written."
            }
        }
    }
}
Write-Host "Validated baseline: a9a69a9; $(@($payload.files).Count) files; 15 migrated items, Bark and 4 equipment items."
foreach ($file in $payload.files) {
    $operation = if ($null -eq $file.before) { 'CREATE' } else { 'UPDATE' }
    Write-Host "$operation $($file.path)"
}
if (!$Apply) { Write-Host 'Preview only. Close Godot and rerun with -Apply to install.'; return }

# =========================================================
# Apply as one checked operation, restoring originals in memory on write failure.
$written = New-Object 'System.Collections.Generic.List[string]'
$originals = @{}
$createdDirectories = New-Object 'System.Collections.Generic.List[string]'
try {
    foreach ($file in $payload.files) {
        $path = Join-Path $ProjectRoot $file.path
        if (Test-Path -LiteralPath $path) { $originals[$path] = [IO.File]::ReadAllBytes($path) }
        else { $originals[$path] = $null }
        $parent = [IO.Path]::GetDirectoryName($path)
        $missing = New-Object 'System.Collections.Generic.List[string]'
        $cursor = $parent
        while (!(Test-Path -LiteralPath $cursor)) { $missing.Add($cursor); $cursor = [IO.Path]::GetDirectoryName($cursor) }
        for ($i = $missing.Count - 1; $i -ge 0; $i--) {
            [IO.Directory]::CreateDirectory($missing[$i]) | Out-Null
            $createdDirectories.Add($missing[$i])
        }
        $written.Add($path)
        [IO.File]::WriteAllText($path, $file.content, $utf8)
        if ((Get-TextHash ([IO.File]::ReadAllText($path))) -ne $file.after) { throw "Write verification failed: $($file.path)" }
    }
} catch {
    $failure = $_
    $rollbackErrors = New-Object 'System.Collections.Generic.List[string]'
    for ($i = $written.Count - 1; $i -ge 0; $i--) {
        $path = $written[$i]
        try {
            if ($null -eq $originals[$path]) { [IO.File]::Delete($path) }
            else { [IO.File]::WriteAllBytes($path, $originals[$path]) }
        } catch { $rollbackErrors.Add($path) }
    }
    for ($i = $createdDirectories.Count - 1; $i -ge 0; $i--) {
        try { [IO.Directory]::Delete($createdDirectories[$i], $false) } catch { }
    }
    if ($rollbackErrors.Count -gt 0) { throw "Installation failed; rollback also failed for: $($rollbackErrors -join ', '). Original failure: $failure" }
    throw "Installation failed; original files restored: $failure"
}
Write-Host 'Phase 2 installed and file contents verified. Open Godot to import SVGs and compile C#.'
Write-Host 'Check old saves, equipment, gathering, berry consumption, Test Cube crafting/placement and save/reload.'
Write-Host 'No gameplay/runtime checks were executed by this installer. Review git diff before committing.'
